CREATE TABLE IF NOT EXISTS hs_data_layouts(tenant_id uuid NOT NULL,collection text NOT NULL,draft_version integer NOT NULL DEFAULT 0,published_version integer,publication_revision integer NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,collection),FOREIGN KEY(tenant_id,collection) REFERENCES hs_data_collections(tenant_id,id));
CREATE TABLE IF NOT EXISTS hs_data_layout_versions(tenant_id uuid NOT NULL,collection text NOT NULL,version integer NOT NULL,definition jsonb NOT NULL,schema_version integer NOT NULL,actor_id text NOT NULL REFERENCES hs_users(id),operation_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,collection,version),FOREIGN KEY(tenant_id,collection) REFERENCES hs_data_collections(tenant_id,id));
CREATE TABLE IF NOT EXISTS hs_data_layout_operations(tenant_id uuid NOT NULL,actor_id text NOT NULL REFERENCES hs_users(id),operation_id uuid NOT NULL,request_hash text NOT NULL,collection text NOT NULL,kind text NOT NULL,applied_version integer NOT NULL,PRIMARY KEY(tenant_id,actor_id,operation_id));
CREATE TABLE IF NOT EXISTS hs_data_layout_previews(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,workspace_id text NOT NULL REFERENCES hs_workspaces(id),actor_id text NOT NULL REFERENCES hs_users(id),collection text NOT NULL,source_version integer NOT NULL,publication_revision integer NOT NULL,schema_version integer NOT NULL,policy_version integer NOT NULL,authority_revision text NOT NULL,review_hash text NOT NULL,expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '10 minutes');
CREATE TABLE IF NOT EXISTS hs_data_layout_publications(tenant_id uuid NOT NULL,collection text NOT NULL,publication_revision integer NOT NULL,source_version integer NOT NULL,actor_id text NOT NULL REFERENCES hs_users(id),operation_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,collection,publication_revision),FOREIGN KEY(tenant_id,collection,source_version) REFERENCES hs_data_layout_versions(tenant_id,collection,version));
DROP TRIGGER IF EXISTS hs_data_layout_versions_immutable ON hs_data_layout_versions;
CREATE TRIGGER hs_data_layout_versions_immutable BEFORE UPDATE OR DELETE ON hs_data_layout_versions FOR EACH ROW EXECUTE FUNCTION hs_data_history_immutable();
DROP TRIGGER IF EXISTS hs_data_layout_publications_immutable ON hs_data_layout_publications;
CREATE TRIGGER hs_data_layout_publications_immutable BEFORE UPDATE OR DELETE ON hs_data_layout_publications FOR EACH ROW EXECUTE FUNCTION hs_data_history_immutable();
ALTER TABLE hs_data_schema_dependencies ADD COLUMN IF NOT EXISTS layout_collection text;
